fn fixture() -> Value {
    let mut v: Value = serde_json::from_str(DUPLICATE_CLIP_IDS).unwrap();
    v["project"]["timelines"][0]["tracks"][1]["clips"][0]["futureKey"] = json!("kept");
    v
}

#[test]
fn a_project_saved_with_two_clips_of_one_id_opens_with_distinct_ids_and_the_graphic_clip_selects() {
    let bytes = serde_json::to_vec(&fixture()).unwrap();
    let project = crate::project_file::project_file().decode(&bytes, None).unwrap();
    let timeline = &project.timelines[0];
    let ids: Vec<_> = timeline.tracks.iter().flat_map(|t| t.clips()).map(|c| c.id).collect();
    assert_eq!(ids.len(), 3);
    assert_eq!(ids.iter().collect::<BTreeSet<_>>().len(), 3, "ids {ids:?}");
    let v1 = &timeline.tracks[0].clips()[0];
    assert_eq!(v1.id.to_string(), "00000000-0000-0000-0000-000000000015", "the first holder keeps its id");
    let graphic = &timeline.tracks[1].clips()[0];
    assert_ne!(graphic.id, v1.id);
    assert_eq!(graphic.name, "Graphic");
    let picked = timeline.primary_clip(&BTreeSet::from([graphic.id])).expect("the Graphic clip selects");
    assert_eq!(picked.id, graphic.id);
    assert_eq!(picked.kind, TrackKind::Video);
    // The key the model does not know stays with the repaired clip when the project is saved again.
    let saved: Value = serde_json::from_slice(&crate::project_file::project_file().encode(&project).unwrap()).unwrap();
    let clip = &saved["project"]["timelines"][0]["tracks"][1]["clips"][0];
    assert_eq!(clip["futureKey"], "kept");
    assert_eq!(clip["id"].as_str().unwrap(), graphic.id.to_string());
}
